// ── Offline Store (IndexedDB) ─────────────────────────────────
const OfflineStore = {
  dbName: 'KeepAI_OfflineDB',
  dbVersion: 1,
  db: null,
  async open() {
    if (this.db) return this.db;
    return new Promise((resolve) => {
      const req = indexedDB.open(this.dbName, this.dbVersion);
      req.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains('notes')) {
          db.createObjectStore('notes', { keyPath: 'id' });
        }
      };
      req.onsuccess = (e) => { this.db = e.target.result; resolve(this.db); };
      req.onerror = () => resolve(null);
    });
  },
  async saveNotes(notes) {
    if (!Array.isArray(notes)) return;
    const db = await this.open();
    if (!db) return;
    try {
      const tx = db.transaction('notes', 'readwrite');
      const store = tx.objectStore('notes');
      store.clear();
      for (const n of notes) store.put(n);
    } catch (_) {}
  },
  async getNotes() {
    const db = await this.open();
    if (!db) return [];
    return new Promise((resolve) => {
      try {
        const tx = db.transaction('notes', 'readonly');
        const req = tx.objectStore('notes').getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => resolve([]);
      } catch (_) { resolve([]); }
    });
  }
};

// ── Reminders & Notifications ─────────────────────────────────
const ReminderService = {
  activeTimer: null,
  init() {
    if (this.activeTimer) clearInterval(this.activeTimer);
    this.activeTimer = setInterval(() => {
      if (state.notes && state.notes.length) {
        this.checkReminders(state.notes);
      }
    }, 15000);

    if ('Notification' in window && Notification.permission === 'default') {
      const askPerm = () => {
        if (Notification.permission === 'default') {
          Notification.requestPermission();
        }
        document.removeEventListener('click', askPerm);
      };
      document.addEventListener('click', askPerm);
    }
  },
  checkReminders(notes) {
    if (!('Notification' in window) || Notification.permission !== 'granted') return;
    const now = new Date();
    (notes || []).forEach(note => {
      if (note.in_trash || note.archived) return;
      if ((note.type === 'event' || note.type === 'appointment') && note.extra?.date) {
        const timeStr = note.extra.time || '09:00';
        const eventDate = new Date(`${note.extra.date}T${timeStr}:00`);
        const diffMinutes = Math.round((eventDate.getTime() - now.getTime()) / 60000);

        if (diffMinutes >= 14 && diffMinutes <= 16) {
          const key = `notif_${note.id}_15m_${note.extra.date}`;
          if (!sessionStorage.getItem(key)) {
            sessionStorage.setItem(key, 'true');
            new Notification(`⏰ Em breve: ${note.title || 'Compromisso'}`, {
              body: `${note.content || 'Compromisso'} às ${timeStr}`,
              icon: '192.png'
            });
          }
        }
      }
    });
  }
};

// ── Google Drive Master Sync ──────────────────────────────────
const GoogleDriveService = {
  accessToken: null,
  tokenExpiresAt: 0,
  syncTimeout: null,
  syncing: false,
  pendingChanges: false,
  folderId: null,
  masterFileId: null,
  status: 'initial',

  init() {
    this.accessToken = localStorage.getItem('keepai_drive_token') || null;
    this.tokenExpiresAt = parseInt(localStorage.getItem('keepai_drive_token_exp') || '0', 10);
    this.folderId = localStorage.getItem('keepai_drive_folder_id') || null;
    this.masterFileId = localStorage.getItem('keepai_drive_file_id') || null;

    window.addEventListener('online', () => {
      this.updateBadge();
      if (this.pendingChanges || this.accessToken) {
        this.scheduleSync(800);
      }
    });

    window.addEventListener('offline', () => {
      this.updateBadge('offline');
    });

    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden' && this.pendingChanges) {
        this.syncWithDrive(false);
      }
    });

    window.addEventListener('beforeunload', () => {
      if (this.pendingChanges) {
        OfflineStore.saveNotes(state.notes);
      }
    });

    this.updateBadge();
  },

  updateBadge(forcedStatus) {
    const badge = qs('#drive-sync-badge');
    if (!badge) return;

    if (!navigator.onLine) {
      badge.style.color = '#94a3b8';
      badge.style.borderColor = 'rgba(148, 163, 184, 0.3)';
      badge.innerHTML = '<i data-lucide="wifi-off" style="width:15px; height:15px;"></i><span id="drive-sync-text">Offline</span>';
      if (window.lucide) lucide.createIcons();
      return;
    }

    const current = forcedStatus || this.status;
    if (current === 'syncing') {
      badge.style.color = '#3b82f6';
      badge.style.borderColor = 'rgba(59, 130, 246, 0.4)';
      badge.innerHTML = '<i data-lucide="refresh-cw" class="spin" style="width:15px; height:15px;"></i><span id="drive-sync-text">Sincronizando...</span>';
    } else if (current === 'synced') {
      badge.style.color = '#10b981';
      badge.style.borderColor = 'rgba(16, 185, 129, 0.4)';
      badge.innerHTML = '<i data-lucide="cloud-check" style="width:15px; height:15px;"></i><span id="drive-sync-text">Sincronizado</span>';
    } else if (current === 'connected') {
      badge.style.color = '#10b981';
      badge.style.borderColor = 'rgba(16, 185, 129, 0.4)';
      badge.innerHTML = '<i data-lucide="cloud" style="width:15px; height:15px; color:#4285F4;"></i><span id="drive-sync-text">Drive</span>';
    } else if (current === 'disconnected') {
      badge.style.color = '#f59e0b';
      badge.style.borderColor = 'rgba(245, 158, 11, 0.4)';
      badge.innerHTML = '<i data-lucide="cloud-off" style="width:15px; height:15px;"></i><span id="drive-sync-text">Conectar Drive</span>';
    } else if (current === 'error') {
      badge.style.color = '#ef4444';
      badge.style.borderColor = 'rgba(239, 68, 68, 0.4)';
      badge.innerHTML = '<i data-lucide="alert-circle" style="width:15px; height:15px;"></i><span id="drive-sync-text">Drive Erro</span>';
    } else {
      if (this.accessToken && Date.now() < this.tokenExpiresAt) {
        badge.style.color = '#10b981';
        badge.style.borderColor = 'rgba(16, 185, 129, 0.4)';
        badge.innerHTML = '<i data-lucide="cloud" style="width:15px; height:15px; color:#4285F4;"></i><span id="drive-sync-text">Drive</span>';
      } else {
        badge.style.color = '#f59e0b';
        badge.style.borderColor = 'rgba(245, 158, 11, 0.4)';
        badge.innerHTML = '<i data-lucide="cloud-off" style="width:15px; height:15px;"></i><span id="drive-sync-text">Conectar Drive</span>';
      }
    }
    if (window.lucide) lucide.createIcons();
  },

  async requestToken(interactive = false) {
    if (this.accessToken && Date.now() < this.tokenExpiresAt - 60000) {
      return this.accessToken;
    }

    // Apenas solicita token via popup do Google se for uma ação direta do usuário (clique)
    // para evitar que o navegador bloqueie o popup no carregamento automático da página.
    if (!interactive) {
      this.status = 'disconnected';
      this.updateBadge('disconnected');
      throw new Error('Google Drive desconectado. Clique em "Conectar Drive" para autorizar.');
    }

    return new Promise((resolve, reject) => {
      if (typeof google === 'undefined' || !google.accounts || !google.accounts.oauth2) {
        return reject(new Error('Google Identity Services não carregado. Recarregue a página.'));
      }
      const client = google.accounts.oauth2.initTokenClient({
        client_id: GOOGLE_CLIENT_ID,
        scope: 'https://www.googleapis.com/auth/drive.file',
        callback: (resp) => {
          if (resp && resp.access_token) {
            this.accessToken = resp.access_token;
            const expiresIn = (resp.expires_in ? parseInt(resp.expires_in, 10) : 3600) * 1000;
            this.tokenExpiresAt = Date.now() + expiresIn;
            localStorage.setItem('keepai_drive_token', this.accessToken);
            localStorage.setItem('keepai_drive_token_exp', String(this.tokenExpiresAt));
            this.status = 'connected';
            this.updateBadge('connected');
            resolve(this.accessToken);
          } else if (resp && resp.error) {
            if (!interactive) {
              this.status = 'disconnected';
              this.updateBadge('disconnected');
            }
            reject(new Error(resp.error_description || resp.error));
          } else {
            if (!interactive) {
              this.status = 'disconnected';
              this.updateBadge('disconnected');
            }
            reject(new Error('Autorização do Google Drive cancelada.'));
          }
        }
      });
      client.requestAccessToken({ prompt: interactive ? 'consent' : '' });
    });
  },

  async getOrCreateFolder(accessToken) {
    if (this.folderId) {
      try {
        const checkRes = await fetch(`https://www.googleapis.com/drive/v3/files/${this.folderId}?fields=id,trashed`, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        if (checkRes.ok) {
          const folderData = await checkRes.json();
          if (!folderData.trashed) return { id: this.folderId };
        }
      } catch (_) {}
    }

    const q = encodeURIComponent("name = 'Keep AI' and mimeType = 'application/vnd.google-apps.folder' and trashed = false");
    const res = await fetch(`https://www.googleapis.com/drive/v3/files?q=${q}&fields=files(id,name)`, {
      headers: { Authorization: `Bearer ${accessToken}` }
    });
    const data = await res.json();
    if (data.files && data.files.length > 0) {
      this.folderId = data.files[0].id;
      localStorage.setItem('keepai_drive_folder_id', this.folderId);
      return data.files[0];
    }

    const createRes = await fetch('https://www.googleapis.com/drive/v3/files?fields=id,name', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        name: 'Keep AI',
        mimeType: 'application/vnd.google-apps.folder',
        description: 'Pasta de notas e backups do aplicativo Keep AI'
      })
    });
    const createdFolder = await createRes.json();
    this.folderId = createdFolder.id;
    localStorage.setItem('keepai_drive_folder_id', this.folderId);
    return createdFolder;
  },

  async findMasterFile(accessToken, folderId) {
    if (this.masterFileId) {
      try {
        const checkRes = await fetch(`https://www.googleapis.com/drive/v3/files/${this.masterFileId}?fields=id,trashed`, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        if (checkRes.ok) {
          const fileData = await checkRes.json();
          if (!fileData.trashed) return { id: this.masterFileId };
        }
      } catch (_) {}
    }

    const q = encodeURIComponent(`name = 'keepai_notes.json' and '${folderId}' in parents and trashed = false`);
    const res = await fetch(`https://www.googleapis.com/drive/v3/files?q=${q}&fields=files(id,name,modifiedTime)`, {
      headers: { Authorization: `Bearer ${accessToken}` }
    });
    const data = await res.json();
    if (data.files && data.files.length > 0) {
      this.masterFileId = data.files[0].id;
      localStorage.setItem('keepai_drive_file_id', this.masterFileId);
      return data.files[0];
    }

    // Se não encontrou keepai_notes.json, verifica se há backups legados na pasta
    const qBackup = encodeURIComponent(`name contains 'keepai_backup_' and '${folderId}' in parents and trashed = false`);
    const resBkp = await fetch(`https://www.googleapis.com/drive/v3/files?q=${qBackup}&orderBy=createdTime desc&fields=files(id,name,createdTime)`, {
      headers: { Authorization: `Bearer ${accessToken}` }
    });
    const dataBkp = await resBkp.json();
    if (dataBkp.files && dataBkp.files.length > 0) {
      return { id: null, legacyBackupFile: dataBkp.files[0] };
    }

    return null;
  },

  async syncWithDrive(interactive = false) {
    if (!navigator.onLine) {
      this.updateBadge('offline');
      if (interactive) toast('Você está offline no momento.', 'info');
      return;
    }

    if (this.syncing) {
      this.pendingChanges = true;
      return;
    }

    let token = null;
    try {
      token = await this.requestToken(interactive);
    } catch (err) {
      if (interactive) toast('Clique em "Conectar Drive" para autorizar a sincronização.', 'info');
      this.status = 'disconnected';
      this.updateBadge('disconnected');
      return;
    }

    this.syncing = true;
    this.updateBadge('syncing');

    try {
      const folder = await this.getOrCreateFolder(token);
      const fileInfo = await this.findMasterFile(token, folder.id);

      let remoteNotes = null;

      if (fileInfo && fileInfo.id) {
        const downloadRes = await fetch(`https://www.googleapis.com/drive/v3/files/${fileInfo.id}?alt=media`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (downloadRes.ok) {
          const driveData = await downloadRes.json();
          remoteNotes = driveData.notes || [];
        }
      } else if (fileInfo && fileInfo.legacyBackupFile) {
        const downloadRes = await fetch(`https://www.googleapis.com/drive/v3/files/${fileInfo.legacyBackupFile.id}?alt=media`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (downloadRes.ok) {
          const driveData = await downloadRes.json();
          remoteNotes = driveData.notes || [];
        }
      }

      // Mesclagem bidirecional inteligente
      let needsLocalReRender = false;
      if (Array.isArray(remoteNotes) && remoteNotes.length > 0) {
        const localMap = new Map();
        (state.notes || []).forEach(n => localMap.set(String(n.id), n));

        remoteNotes.forEach(rNote => {
          const rId = String(rNote.id);
          if (!localMap.has(rId)) {
            state.notes.push(rNote);
            needsLocalReRender = true;
          } else {
            const lNote = localMap.get(rId);
            const lTime = new Date(lNote.updated_at || lNote.created_at || 0).getTime();
            const rTime = new Date(rNote.updated_at || rNote.created_at || 0).getTime();
            if (rTime > lTime) {
              const idx = state.notes.findIndex(n => String(n.id) === rId);
              if (idx !== -1) {
                state.notes[idx] = rNote;
                needsLocalReRender = true;
              }
            }
          }
        });

        if (needsLocalReRender) {
          await OfflineStore.saveNotes(state.notes);
          renderNotes();
          ReminderService.checkReminders(state.notes);
        }
      }

      // Enviar dados atualizados para o arquivo mestre no Google Drive
      const payload = this.createBackupPayload();
      const payloadJson = JSON.stringify(payload, null, 2);

      if (this.masterFileId) {
        const updateRes = await fetch(`https://www.googleapis.com/upload/drive/v3/files/${this.masterFileId}?uploadType=media`, {
          method: 'PATCH',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json'
          },
          body: payloadJson
        });
        if (!updateRes.ok) {
          this.masterFileId = null;
          localStorage.removeItem('keepai_drive_file_id');
          await this.syncWithDrive(interactive);
          return;
        }
      } else {
        const metadata = {
          name: 'keepai_notes.json',
          parents: [folder.id],
          description: 'Base de dados mestre de notas do Keep AI'
        };
        const boundary = '-------KeepAiMasterBoundary';
        const delimiter = "\r\n--" + boundary + "\r\n";
        const close_delim = "\r\n--" + boundary + "--";
        const multipartBody =
          delimiter +
          'Content-Type: application/json; charset=UTF-8\r\n\r\n' +
          JSON.stringify(metadata) +
          delimiter +
          'Content-Type: application/json\r\n\r\n' +
          payloadJson +
          close_delim;

        const createRes = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name', {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': `multipart/related; boundary="${boundary}"`
          },
          body: multipartBody
        });
        if (createRes.ok) {
          const newFileData = await createRes.json();
          this.masterFileId = newFileData.id;
          localStorage.setItem('keepai_drive_file_id', this.masterFileId);
        }
      }

      this.status = 'synced';
      this.pendingChanges = false;
      this.updateBadge('synced');
      if (interactive) {
        toast(`✅ Sincronizado com o Google Drive! (${state.notes.length} notas)`, 'success');
      }
    } catch (err) {
      console.error('Erro na sincronização Drive:', err);
      if (err.message && (err.message.includes('401') || err.message.includes('token'))) {
        this.accessToken = null;
        localStorage.removeItem('keepai_drive_token');
        this.status = 'disconnected';
      } else {
        this.status = 'error';
      }
      this.updateBadge();
      if (interactive) {
        toast('Erro ao sincronizar com Google Drive: ' + err.message, 'error');
      }
    } finally {
      this.syncing = false;
      if (this.pendingChanges) {
        this.pendingChanges = false;
        this.scheduleSync(2000);
      }
    }
  },

  scheduleSync(delayMs = 1500) {
    this.pendingChanges = true;
    if (this.syncTimeout) clearTimeout(this.syncTimeout);
    this.syncTimeout = setTimeout(() => {
      this.syncWithDrive(false);
    }, delayMs);
  },

  async uploadBackup(accessToken, folderId, backupData) {
    const now = new Date();
    const datePart = now.toISOString().split('T')[0];
    const timePart = `${String(now.getHours()).padStart(2, '0')}h${String(now.getMinutes()).padStart(2, '0')}`;
    const filename = `keepai_backup_${datePart}_${timePart}.json`;

    const metadata = {
      name: filename,
      parents: [folderId],
      description: `Backup do Keep AI com ${backupData.notes.length} notas em ${now.toLocaleString('pt-BR')}`
    };

    const boundary = '-------KeepAiBoundary314159';
    const delimiter = "\r\n--" + boundary + "\r\n";
    const close_delim = "\r\n--" + boundary + "--";

    const multipartRequestBody =
      delimiter +
      'Content-Type: application/json; charset=UTF-8\r\n\r\n' +
      JSON.stringify(metadata) +
      delimiter +
      'Content-Type: application/json\r\n\r\n' +
      JSON.stringify(backupData, null, 2) +
      close_delim;

    const res = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,webViewLink', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': `multipart/related; boundary="${boundary}"`
      },
      body: multipartRequestBody
    });

    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.error?.message || 'Falha no envio ao Google Drive.');
    }

    return await res.json();
  },

  createBackupPayload() {
    return {
      app: 'Keep AI',
      version: '46.5.0',
      exported_at: new Date().toISOString(),
      user: {
        email: state.user?.email || localStorage.getItem('keepai_user_email') || 'fbr4g4@gmail.com',
        name: state.user?.display_name || localStorage.getItem('keepai_user_name') || 'Usuário'
      },
      total_notes: state.notes ? state.notes.length : 0,
      notes: state.notes || []
    };
  }
};
window.GoogleDriveService = GoogleDriveService;

// ── Persistência Local Imediata ──────────────────────────────
async function persistNotesLocal() {
  try {
    await OfflineStore.saveNotes(state.notes);
  } catch (e) {
    console.error('Erro ao salvar no IndexedDB:', e);
  }
  ReminderService.checkReminders(state.notes);
  GoogleDriveService.scheduleSync();
}
window.persistNotesLocal = persistNotesLocal;

