// ── Google OAuth 2.0 Authentication ──────────────────────────
let googleTokenClient = null;

function initGoogleAuth() {
  if (typeof google === 'undefined' || !google.accounts || !google.accounts.oauth2) {
    return;
  }
  if (googleTokenClient) {
    return;
  }
  googleTokenClient = google.accounts.oauth2.initTokenClient({
    client_id: GOOGLE_CLIENT_ID,
    scope: 'https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/userinfo.email openid',
    callback: async (response) => {
      if (response && response.access_token) {
        showLoading('Entrando com Google...');
        try {
          const res = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
            headers: { Authorization: `Bearer ${response.access_token}` }
          });
          const googleUser = await res.json();
          await handleGoogleLoginSuccess(googleUser, response.access_token);
        } catch (err) {
          hideLoading();
          toast('Erro ao autenticar com Google: ' + (err.message || err), 'error');
        }
      } else if (response && response.error) {
        hideLoading();
        if (response.error !== 'popup_closed_by_user') {
          toast('Autenticação Google cancelada.', 'info');
        }
      }
    }
  });
}

async function handleGoogleLoginSuccess(googleUser, accessToken) {
  try {
    const payload = {
      access_token: accessToken,
      email: googleUser.email,
      name: googleUser.name,
      picture: googleUser.picture
    };

    const data = await api('POST', '/auth.php?action=google', payload);
    state.token = data.token;
    state.user = data.user;
    sessionStorage.setItem('keepai_token', data.token);

    const email = (googleUser.email || '').toLowerCase().trim();
    const isAdmin = (email === 'fbr4g4@gmail.com' || email === 'fb4g4@gmail.com');
    if (isAdmin) {
      localStorage.setItem('user_credits', '999999');
      localStorage.setItem('user_role', 'admin');
      state.credits = 999999;
      console.log('✅ Modo Desenvolvedor / VIP Ativado para ' + email);
    } else {
      state.credits = data.user?.credits || 10;
    }

    localStorage.setItem('keepai_user_email', data.user.email);
    localStorage.setItem('keepai_user_name', data.user.display_name || '');

    // Transiciona imediatamente para o app
    showApp();
    populateUserUI();
    updateCreditsUI();

    GoogleDriveService.init();

    await loadNotes();
    hideLoading();
    toast(`Bem-vindo, ${data.user.display_name || 'ao Keep AI'}!`, 'success');
  } catch (err) {
    hideLoading();
    console.error('Erro no login Google:', err);
    toast('Erro ao processar login com Google: ' + err.message, 'error');
  }
}

window.conectarGoogle = function() {
  if (!googleTokenClient) {
    initGoogleAuth();
  }
  if (googleTokenClient) {
    googleTokenClient.requestAccessToken({ prompt: 'select_account' });
  } else {
    showLoading('Carregando Google...');
    let attempts = 0;
    const interval = setInterval(() => {
      attempts++;
      initGoogleAuth();
      if (googleTokenClient) {
        clearInterval(interval);
        hideLoading();
        googleTokenClient.requestAccessToken({ prompt: 'select_account' });
      } else if (attempts >= 15) {
        clearInterval(interval);
        hideLoading();
        toast('Serviço de login do Google indisponível no momento. Tente novamente em instantes.', 'error');
      }
    }, 200);
  }
};

