// ── API Helper ────────────────────────────────────────────────
async function api(method, endpoint, body = null) {
  const headers = {};
  if (state.token) {
    headers['Authorization'] = 'Bearer ' + state.token;
  }
  const opts = { method, headers };
  if (body !== null) {
    headers['Content-Type'] = 'application/json';
    opts.body = JSON.stringify(body);
  }
  const res  = await fetch(API + endpoint, opts);
  const data = await res.json();
  if (!res.ok) {
    if (res.status === 401) {
      sessionStorage.removeItem('keepai_token');
      state.token = null;
    }
    const err = new Error(data.error || 'API error');
    err.status = res.status;
    throw err;
  }
  return data;
}

// ── Notes ─────────────────────────────────────────────────────
async function loadNotes() {
  try {
    let cached = await OfflineStore.getNotes();
    if (!cached || cached.length === 0) {
      cached = JSON.parse(JSON.stringify(INITIAL_SEEDED_NOTES));
      await OfflineStore.saveNotes(cached);
    }
    state.notes = cached;
    renderNotes();
    ReminderService.checkReminders(state.notes);

    if (navigator.onLine) {
      GoogleDriveService.syncWithDrive(false);
    }
  } catch (err) {
    console.error('Erro em loadNotes:', err);
    if (!state.notes || !state.notes.length) {
      state.notes = JSON.parse(JSON.stringify(INITIAL_SEEDED_NOTES));
      renderNotes();
    }
  }
}

function renderNotes() {
  const grid = qs('#notes-grid');
  if (!grid) return;
  const currentLayout = (typeof LayoutManager !== 'undefined' && LayoutManager.current)
    ? LayoutManager.current
    : (localStorage.getItem('keepai-layout') || 'grid');
  grid.classList.toggle('layout-grid', currentLayout === 'grid');
  grid.classList.toggle('layout-list', currentLayout === 'list');
  let notes  = [...(state.notes || [])];

  // Update Section Title and Controls
  const titles = {
    'all': t('notes_header.all_title'),
    'pinned': t('notes_header.pinned_title'),
    'archived': t('notes_header.archived_title'),
    'trash': t('notes_header.trash_title'),
    'shopping-list': t('notes_header.checklist_title'),
    'checklist': t('notes_header.checklist_title'),
    'agenda': t('notes_header.agenda_title'),
    'event': t('notes_header.agenda_title'),
    'appointment': t('notes_header.agenda_title')
  };
  const titleEl = qs('#filter-title');
  if (titleEl) titleEl.textContent = titles[state.filter] || t('notes_header.all_title');

  const emptyTrashBtn = qs('#btn-empty-trash');
  const aiBtn = qs('#btn-open-ai');
  const newNoteBtn = qs('#btn-new-note');
  const askAiBtn = qs('#btn-open-ask-ai');
  const visionBtn = qs('#btn-open-vision');

  if (state.filter === 'trash') {
    if (emptyTrashBtn) emptyTrashBtn.style.display = 'inline-flex';
    if (aiBtn) aiBtn.style.display = 'none';
    if (newNoteBtn) newNoteBtn.style.display = 'none';
    if (askAiBtn) askAiBtn.style.display = 'none';
    if (visionBtn) visionBtn.style.display = 'none';
  } else {
    if (emptyTrashBtn) emptyTrashBtn.style.display = 'none';
    if (aiBtn) aiBtn.style.display = 'inline-flex';
    if (newNoteBtn) newNoteBtn.style.display = 'inline-flex';
    if (askAiBtn) askAiBtn.style.display = 'inline-flex';
    if (visionBtn) visionBtn.style.display = 'inline-flex';
  }

  // Filtragem por modo/categoria
  if (state.filter === 'trash') {
    notes = notes.filter(n => n.in_trash || n.deleted_at);
  } else if (state.filter === 'archived') {
    notes = notes.filter(n => n.archived && !n.in_trash && !n.deleted_at);
  } else if (state.filter === 'pinned') {
    notes = notes.filter(n => n.pinned && !n.archived && !n.in_trash && !n.deleted_at);
  } else if (state.filter === 'shopping-list' || state.filter === 'checklist') {
    notes = notes.filter(n => (n.type === 'shopping-list' || n.type === 'checklist') && !n.archived && !n.in_trash && !n.deleted_at);
  } else if (state.filter === 'agenda' || state.filter === 'event' || state.filter === 'appointment') {
    notes = notes.filter(n => (n.type === 'event' || n.type === 'appointment' || n.type === 'agenda') && !n.archived && !n.in_trash && !n.deleted_at);
  } else {
    // 'all'
    notes = notes.filter(n => !n.archived && !n.in_trash && !n.deleted_at);
  }

  // Busca textual
  if (state.searchQuery) {
    const q = state.searchQuery.toLowerCase().trim();
    notes = notes.filter(n => {
      const matchTitle   = (n.title || '').toLowerCase().includes(q);
      const matchContent = (n.content || '').toLowerCase().includes(q);
      const matchTags    = (n.tags || []).some(t => t.toLowerCase().includes(q));
      
      // Check list items
      let matchItems = false;
      if (n.type === 'shopping-list' && n.extra?.items) {
        matchItems = n.extra.items.some(item => {
          const txt = typeof item === 'object' ? item.text : item;
          return (txt || '').toLowerCase().includes(q);
        });
      }

      return matchTitle || matchContent || matchTags || matchItems;
    });
  }

  // Ordenação
  if (state.filter !== 'trash') {
    notes.sort((a, b) => {
      if (!!a.pinned !== !!b.pinned) return a.pinned ? -1 : 1;
      const posA = a.position !== undefined && a.position !== null ? a.position : 999999;
      const posB = b.position !== undefined && b.position !== null ? b.position : 999999;
      if (posA !== posB) return posA - posB;
      return (b.id || 0) - (a.id || 0);
    });
  } else {
    notes.sort((a, b) => (b.id || 0) - (a.id || 0));
  }

  const pluralS = (notes.length !== 1) ? 's' : '';
  qs('#notes-count').textContent = t('notes_header.count_notes', { count: notes.length, s: pluralS });

  if (!notes.length) {
    grid.classList.add('empty-state');
    let emptyIcon = '📝';
    let emptyMsg = t('empty.default_title');
    let emptySub = t('empty.default_sub');

    if (state.filter === 'trash') {
      emptyIcon = '🗑️';
      emptyMsg = t('empty.trash_title');
      emptySub = t('empty.trash_sub');
    } else if (state.filter === 'archived') {
      emptyIcon = '📦';
      emptyMsg = t('empty.archived_title');
      emptySub = t('empty.archived_sub');
    } else if (state.filter === 'pinned') {
      emptyIcon = '📌';
      emptyMsg = t('empty.pinned_title');
      emptySub = t('empty.pinned_sub');
    } else if (state.filter === 'shopping-list' || state.filter === 'checklist') {
      emptyIcon = '☑️';
      emptyMsg = t('empty.checklist_title');
      emptySub = t('empty.checklist_sub');
    } else if (state.filter === 'agenda' || state.filter === 'event' || state.filter === 'appointment') {
      emptyIcon = '📅';
      emptyMsg = t('empty.agenda_title');
      emptySub = t('empty.agenda_sub');
    } else if (state.searchQuery) {
      emptyIcon = '🔍';
      emptyMsg = t('empty.search_title');
      emptySub = t('empty.search_sub');
    }

    grid.innerHTML = `
      <div class="empty-state-card">
        <div class="empty-icon">${emptyIcon}</div>
        <h3>${emptyMsg}</h3>
        <p>${emptySub}</p>
      </div>`;
    return;
  }

  grid.classList.remove('empty-state');
  grid.innerHTML = '';
  notes.forEach((note, i) => {
    const el = buildNoteCard(note, i);
    grid.appendChild(el);
  });
  
  if (window.lucide) lucide.createIcons();

  // Initialize drag-and-drop reordering
  initSortable();
}
let sortableInstance = null;
function initSortable() {
  const grid = qs('#notes-grid');
  if (!grid || !window.Sortable) return;

  if (sortableInstance) {
    sortableInstance.destroy();
    sortableInstance = null;
  }

  const isSearchActive = !!state.searchQuery;
  const isFilterAllOrArchived = state.filter === 'all' || state.filter === 'archived';

  if (isSearchActive || !isFilterAllOrArchived) return;

  sortableInstance = new Sortable(grid, {
    animation: 350,
    ghostClass: 'sortable-ghost',
    dragClass: 'sortable-drag',
    handle: '.note-card',
    delay: 200,
    delayOnTouchOnly: true,
    touchStartThreshold: 5,
    onEnd: async () => {
      const ids = Array.from(grid.querySelectorAll('.note-card')).map(el => el.dataset.id);
      await saveNoteOrder(ids);
    }
  });
}

async function saveNoteOrder(ids) {
  try {
    const orderMap = new Map();
    ids.forEach((id, idx) => orderMap.set(String(id), idx));

    state.notes.forEach(n => {
      const idStr = String(n.id);
      if (orderMap.has(idStr)) {
        n.position = orderMap.get(idStr);
      }
    });
    await persistNotesLocal();
  } catch (err) {
    console.error('Erro ao salvar nova ordem:', err);
  }
}

// ── Mobile Swipe Gestures ─────────────────────────────────────
function attachCardGestures(cardEl, note) {
  if (!cardEl || !note) return;

  let startX = 0;
  let startY = 0;
  let currentX = 0;
  let isSwiping = false;

  cardEl.addEventListener('touchstart', (e) => {
    if (state.selectionMode) return;
    if (e.touches.length !== 1) return;
    startX = e.touches[0].clientX;
    startY = e.touches[0].clientY;
    currentX = startX;
    isSwiping = false;
  }, { passive: true });

  cardEl.addEventListener('touchmove', (e) => {
    if (state.selectionMode) return;
    if (e.touches.length !== 1) return;
    currentX = e.touches[0].clientX;
    const diffX = currentX - startX;
    const diffY = e.touches[0].clientY - startY;

    if (Math.abs(diffY) > Math.abs(diffX) && !isSwiping) return;

    if (Math.abs(diffX) > 20) {
      isSwiping = true;
      cardEl.style.transform = `translateX(${diffX * 0.35}px)`;
      cardEl.style.transition = 'none';
      if (diffX > 60) {
        cardEl.style.boxShadow = '0 0 15px rgba(245, 158, 11, 0.4)';
      } else if (diffX < -60) {
        cardEl.style.boxShadow = '0 0 15px rgba(59, 130, 246, 0.4)';
      }
    }
  }, { passive: true });

  cardEl.addEventListener('touchend', () => {
    if (!isSwiping || state.selectionMode) return;
    cardEl.style.transition = 'transform 0.25s ease, box-shadow 0.25s ease';
    cardEl.style.transform = '';
    cardEl.style.boxShadow = '';

    const diffX = currentX - startX;
    if (diffX > 80) {
      togglePin(note.id, note.pinned);
    } else if (diffX < -80) {
      archiveNote(note.id, note.archived);
    }
    isSwiping = false;
  }, { passive: true });
}

// ── Batch Selection & Actions ─────────────────────────────────
let justEnteredSelectionMode = false;

window.enterSelectionMode = (initialId) => {
  state.selectionMode = true;
  state.selectedNoteIds = new Set([initialId]);
  justEnteredSelectionMode = true;
  setTimeout(() => { justEnteredSelectionMode = false; }, 350);

  if (typeof sortableInstance !== 'undefined' && sortableInstance) {
    try { sortableInstance.option('disabled', true); } catch(e) {}
  }

  qs('#notes-grid')?.classList.add('selection-mode-active');
  qs('#batch-action-bar')?.classList.remove('hidden');

  updateSelectionUI();
};

window.exitSelectionMode = () => {
  state.selectionMode = false;
  state.selectedNoteIds.clear();

  if (typeof sortableInstance !== 'undefined' && sortableInstance) {
    try { sortableInstance.option('disabled', false); } catch(e) {}
  }

  qs('#notes-grid')?.classList.remove('selection-mode-active');
  qs('#batch-action-bar')?.classList.add('hidden');

  qsa('.note-card.selected').forEach(c => c.classList.remove('selected'));
  qsa('.note-card.selectable').forEach(c => c.classList.remove('selectable'));
};

window.toggleNoteSelection = (noteId) => {
  if (state.selectedNoteIds.has(noteId)) {
    state.selectedNoteIds.delete(noteId);
  } else {
    state.selectedNoteIds.add(noteId);
  }

  if (state.selectedNoteIds.size === 0) {
    exitSelectionMode();
    return;
  }

  updateSelectionUI();
};

function updateSelectionUI() {
  const count = state.selectedNoteIds.size;
  const numEl = qs('#batch-count-num');
  const wordEl = qs('.batch-count-word');
  const countEl = qs('#batch-count');
  const isEn = getLang() === 'en';
  if (numEl) {
    numEl.textContent = count;
    if (wordEl) wordEl.textContent = isEn ? 'selected' : (count > 1 ? 'selecionadas' : 'selecionada');
  } else if (countEl) {
    countEl.textContent = isEn ? `${count} selected` : `${count} selecionada${count > 1 ? 's' : ''}`;
  }

  qsa('.note-card').forEach(card => {
    const id = Number(card.dataset.id);
    const isSelected = state.selectedNoteIds.has(id);
    card.classList.toggle('selected', isSelected);
    card.classList.add('selectable');
  });

  const isTrash = state.filter === 'trash';
  const isArchived = state.filter === 'archived';

  const archiveBtn = qs('#btn-batch-archive');
  const trashBtn = qs('#btn-batch-trash');
  const restoreBtn = qs('#btn-batch-restore');
  const deletePermBtn = qs('#btn-batch-delete-permanent');
  const pinBtn = qs('#btn-batch-pin');

  if (isTrash) {
    if (archiveBtn) archiveBtn.style.display = 'none';
    if (trashBtn) trashBtn.style.display = 'none';
    if (pinBtn) pinBtn.style.display = 'none';
    if (restoreBtn) restoreBtn.style.display = 'inline-flex';
    if (deletePermBtn) deletePermBtn.style.display = 'inline-flex';
  } else {
    if (archiveBtn) {
      archiveBtn.style.display = 'inline-flex';
      archiveBtn.title = isArchived 
        ? (isEn ? 'Unarchive notes' : 'Desarquivar notas') 
        : (isEn ? 'Archive notes' : 'Arquivar notas');
      archiveBtn.innerHTML = `<i data-lucide="${isArchived ? 'rotate-ccw' : 'archive'}"></i>`;
    }
    if (trashBtn) trashBtn.style.display = 'inline-flex';
    if (pinBtn) pinBtn.style.display = 'inline-flex';
    if (restoreBtn) restoreBtn.style.display = 'none';
    if (deletePermBtn) deletePermBtn.style.display = 'none';
  }

  if (window.lucide) lucide.createIcons();
}

function initBatchActionBar() {
  qs('#btn-batch-close')?.addEventListener('click', exitSelectionMode);

  qs('#btn-batch-select-all')?.addEventListener('click', () => {
    const visibleCards = qsa('.note-card');
    const visibleIds = Array.from(visibleCards).map(c => Number(c.dataset.id)).filter(Boolean);
    const allSelected = visibleIds.length > 0 && visibleIds.every(id => state.selectedNoteIds.has(id));

    if (allSelected) {
      exitSelectionMode();
    } else {
      visibleIds.forEach(id => state.selectedNoteIds.add(id));
      updateSelectionUI();
    }
  });

  qs('#btn-batch-pin')?.addEventListener('click', async () => {
    if (state.selectedNoteIds.size === 0) return;
    const count = state.selectedNoteIds.size;
    const selectedNotes = state.notes.filter(n => state.selectedNoteIds.has(n.id));
    const allPinned = selectedNotes.every(n => n.pinned);
    const targetPin = !allPinned;

    selectedNotes.forEach(n => {
      n.pinned = targetPin;
      n.updated_at = new Date().toISOString();
    });

    await persistNotesLocal();
    exitSelectionMode();
    renderNotes();
    toast(`📌 ${count} nota(s) ${targetPin ? 'fixada(s)' : 'desafixada(s)'}!`, 'success');
  });

  qs('#btn-batch-color')?.addEventListener('click', (e) => {
    showBatchColorPicker(e);
  });

  qs('#btn-batch-archive')?.addEventListener('click', async () => {
    if (state.selectedNoteIds.size === 0) return;
    const isArchivedFilter = state.filter === 'archived';
    const targetArchived = !isArchivedFilter;
    const count = state.selectedNoteIds.size;

    state.notes.forEach(note => {
      if (state.selectedNoteIds.has(note.id)) {
        note.archived = targetArchived;
        note.updated_at = new Date().toISOString();
      }
    });

    await persistNotesLocal();
    exitSelectionMode();
    renderNotes();
    toast(`📦 ${count} nota(s) ${targetArchived ? 'arquivada(s)' : 'desarquivada(s)'}!`, 'success');
  });

  qs('#btn-batch-trash')?.addEventListener('click', async () => {
    if (state.selectedNoteIds.size === 0) return;
    const count = state.selectedNoteIds.size;
    const idsToDelete = new Set(state.selectedNoteIds);

    state.notes.forEach(note => {
      if (idsToDelete.has(note.id)) {
        note.in_trash = true;
        note.updated_at = new Date().toISOString();
      }
    });

    await persistNotesLocal();
    exitSelectionMode();
    renderNotes();

    showUndoToast(`${count} nota(s) movida(s) para a lixeira.`, async () => {
      state.notes.forEach(note => {
        if (idsToDelete.has(note.id)) {
          note.in_trash = false;
          note.updated_at = new Date().toISOString();
        }
      });
      await persistNotesLocal();
      renderNotes();
      toast('Ação desfeita.', 'info');
    });
  });

  qs('#btn-batch-restore')?.addEventListener('click', async () => {
    if (state.selectedNoteIds.size === 0) return;
    const count = state.selectedNoteIds.size;

    state.notes.forEach(note => {
      if (state.selectedNoteIds.has(note.id)) {
        note.in_trash = false;
        note.updated_at = new Date().toISOString();
      }
    });

    await persistNotesLocal();
    exitSelectionMode();
    renderNotes();
    toast(`♻️ ${count} nota(s) restaurada(s)!`, 'success');
  });

  qs('#btn-batch-delete-permanent')?.addEventListener('click', async () => {
    if (state.selectedNoteIds.size === 0) return;
    const count = state.selectedNoteIds.size;
    if (!confirm(`Tem certeza que deseja excluir definitivamente ${count} nota(s)? Esta ação não pode ser desfeita.`)) {
      return;
    }

    state.notes = state.notes.filter(n => !state.selectedNoteIds.has(n.id));
    await persistNotesLocal();
    exitSelectionMode();
    renderNotes();
    toast(`🗑️ ${count} nota(s) excluída(s) definitivamente.`, 'info');
  });

  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && state.selectionMode) {
      exitSelectionMode();
    }
  });
}

function showBatchColorPicker(e) {
  if (e && e.stopPropagation) e.stopPropagation();
  const existing = qs('.color-palette');
  if (existing) existing.remove();

  const palette = document.createElement('div');
  palette.className = 'color-palette';
  palette.style.position = 'fixed';
  const btn = qs('#btn-batch-color');
  if (btn) {
    const rect = btn.getBoundingClientRect();
    palette.style.top = `${rect.bottom + 8}px`;
    palette.style.left = `${Math.max(10, Math.min(rect.left - 60, window.innerWidth - 220))}px`;
    palette.style.zIndex = '1300';
  }

  COLORS.forEach(color => {
    const swatch = document.createElement('div');
    swatch.className = 'color-swatch';
    swatch.style.backgroundColor = color;
    swatch.onclick = async (ev) => {
      ev.stopPropagation();
      palette.remove();
      const count = state.selectedNoteIds.size;
      state.notes.forEach(note => {
        if (state.selectedNoteIds.has(note.id)) {
          note.color = color;
          note.updated_at = new Date().toISOString();
        }
      });
      await persistNotesLocal();
      exitSelectionMode();
      renderNotes();
      toast(`🎨 Cor aplicada a ${count} nota(s)!`, 'success');
    };
    palette.appendChild(swatch);
  });

  document.body.appendChild(palette);
  setTimeout(() => {
    const closePicker = (ev) => {
      if (!palette.contains(ev.target)) {
        palette.remove();
        document.removeEventListener('click', closePicker);
      }
    };
    document.addEventListener('click', closePicker);
  }, 50);
}

function buildNoteCard(note, index) {
  const isSelected = state.selectedNoteIds.has(note.id);
  const div = document.createElement('div');
  div.className = `note-card type-${note.type}${note.pinned ? ' pinned' : ''}${isSelected ? ' selected' : ''}${state.selectionMode ? ' selectable' : ''}`;
  div.style.animationDelay = `${index * 0.05}s`;
  div.dataset.id = note.id;

  const typeLabels = {
    'generic':       t('card.note_badge'),
    'shopping-list': t('card.checklist_badge'),
    'checklist':     t('card.checklist_badge'),
    'event':         t('card.agenda_badge'),
    'appointment':   t('card.agenda_badge'),
    'agenda':        t('card.agenda_badge'),
  };

  let itemsHtml = '';
  if ((note.type === 'shopping-list' || note.type === 'checklist') && note.extra?.items?.length) {
    const totalItems = note.extra.items.length;
    // Se tiver até 7 itens, mostra todos. Se tiver mais de 7, mostra os 6 primeiros e o chip "+ X itens restantes"
    const shouldTruncate = totalItems > 7;
    const maxVisible = shouldTruncate ? 6 : totalItems;
    const visibleItems = note.extra.items.slice(0, maxVisible);
    const remainingCount = totalItems - maxVisible;

    itemsHtml = '<ul class="note-items">' +
      visibleItems.map((item, i) => {
        const itemText = typeof item === 'object' ? (item.text || '') : item;
        const isDone = typeof item === 'object' ? !!item.done : false;
        return `<li class="note-item ${isDone ? 'done' : ''}" data-index="${i}">
          <input type="checkbox" ${isDone ? 'checked' : ''} onchange="toggleItem(this, ${note.id}, ${i})"> <span>${esc(itemText)}</span>
         </li>`;
      }).join('') + '</ul>';

    if (shouldTruncate && remainingCount > 0) {
      const remainingLabel = remainingCount === 1
        ? t('card.item_remaining')
        : t('card.items_remaining', { count: remainingCount });
      const hintTitle = getLang() === 'en'
        ? `Click card to open all ${totalItems} items`
        : `Clique no card para abrir todos os ${totalItems} itens`;
      itemsHtml += `
        <div class="note-items-more" title="${hintTitle}">
          <i data-lucide="plus" style="width: 12px; height: 12px; stroke-width: 2.5;"></i>
          <span>${remainingLabel}</span>
        </div>`;
    }
  }

  let dateChip = '';
  if ((note.type === 'event' || note.type === 'appointment' || note.type === 'agenda') && (note.extra?.date || note.extra?.time)) {
    let dt = note.extra.date || '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(dt)) {
      const [y, m, d] = dt.split('-');
      dt = getLang() === 'en' ? `${m}/${d}` : `${d}/${m}`;
    }
    const timeConnector = getLang() === 'en' ? ' at ' : ' às ';
    const timeStr = note.extra.time ? `${timeConnector}${note.extra.time}` : '';
    const personStr = note.extra.person ? ` · 👤 ${esc(note.extra.person)}` : '';
    const locStr = note.extra.location ? ` · 📍 ${esc(note.extra.location)}` : '';
    dateChip = `<div class="note-date-chip">🗓 ${dt}${timeStr}${personStr}${locStr}</div>`;
  }

  const tags = (note.tags || []).map(t => `<span class="note-tag">#${esc(t)}</span>`).join('');
  const tagsHtml = tags ? `<div class="note-tags">${tags}</div>` : '';

  const calBtn = (note.type === 'event' || note.type === 'appointment' || note.type === 'agenda')
    ? `<button class="note-action-btn calendar-btn" title="${t('card.calendar_title')}" onclick="addToCalendar(${note.id})">
         <i data-lucide="calendar-plus"></i>
       </button>`
    : '';

  const isTrash = state.filter === 'trash';
  const actionButtons = isTrash
    ? `
      <button class="note-action-btn" title="${t('card.restore_title')}" onclick="restoreNote(${note.id})">
        <i data-lucide="rotate-ccw"></i>
      </button>
      <button class="note-action-btn delete" title="${t('card.delete_permanent_title')}" onclick="deleteNotePermanent(${note.id})" style="margin-left:auto">
        <i data-lucide="trash-2"></i>
      </button>
    `
    : `
      <button class="note-action-btn pin-btn" title="${note.pinned ? t('card.unpin_title') : t('card.pin_title')}" onclick="togglePin(${note.id},${note.pinned})">
        <i data-lucide="pin"></i>
      </button>
      <button class="note-action-btn" title="${t('card.color_title')}" onclick="showColorPicker(event, ${note.id})">
        <i data-lucide="palette"></i>
      </button>
      <button class="note-action-btn" title="${t('card.edit_title')}" onclick="openEditModal(${note.id})">
        <i data-lucide="edit-3"></i>
      </button>
      ${calBtn}
      <button class="note-action-btn" title="${note.archived ? t('card.restore_title') : t('card.archive_title')}" onclick="archiveNote(${note.id},${note.archived})">
        <i data-lucide="${note.archived ? 'rotate-ccw' : 'archive'}"></i>
      </button>
      <button class="note-action-btn" title="${t('card.share_title')}" onclick="shareNote(${note.id})">
        <i data-lucide="share-2"></i>
      </button>
      <button class="note-action-btn delete" title="${t('card.delete_title')}" onclick="deleteNote(${note.id})" style="margin-left:auto">
        <i data-lucide="trash-2"></i>
      </button>
    `;

  const isLongText = !itemsHtml && note.content && (note.content.length > 250 || (note.content.match(/\n/g) || []).length >= 7);
  const textMoreHint = isLongText
    ? `<div class="note-text-more" title="${getLang() === 'en' ? 'Click card to view full note' : 'Clique no card para ler a nota completa'}">
         <span>${t('card.more_text')}</span>
       </div>`
    : '';

  div.innerHTML = `
    <div class="note-select-check" title="${t('card.select_title')}">
      <i data-lucide="check"></i>
    </div>
    ${(() => {
      const rawImg = note.extra?.image || note.image;
      const illustrationNames = ['lista.png', 'checklist.png', 'notas.png', 'evento.png', 'compromisso.png'];
      
      const defaults = {
        'shopping-list': 'lista.png',
        'checklist':     'lista.png',
        'event':         'evento.png',
        'appointment':   'evento.png',
        'agenda':        'evento.png',
        'generic':       'notas.png'
      };

      const isIllustration = !rawImg || illustrationNames.some(name => typeof rawImg === 'string' && rawImg.includes(name));
      const defImg = isIllustration ? (defaults[note.type] || 'notas.png') : rawImg;

      if (isIllustration) {
        return `<div class="note-card-image default-bg"><img src="${defImg}" alt="Pattern"></div>`;
      }
      return `<div class="note-card-image"><img src="${rawImg}" alt="Note Image"></div>`;
    })()}
    <div class="note-card-content">
      ${dateChip ? '' : `<div class="note-type-badge">${typeLabels[note.type] || t('card.note_badge')}</div>`}
      ${dateChip}
      ${note.title ? `<div class="note-title" style="margin-top: 8px;">${esc(note.title)}</div>` : ''}
      ${itemsHtml || (note.content ? `<div class="note-content">${esc(note.content)}</div>` : '')}
      ${textMoreHint}
      ${tagsHtml}
    </div>
    <div class="note-actions">
      ${actionButtons}
    </div>`;

  // Long-press detection (Mobile touch + Desktop click & hold)
  let pressTimer = null;
  let hasMoved = false;
  let startX = 0;
  let startY = 0;

  const startPress = (clientX, clientY) => {
    hasMoved = false;
    startX = clientX;
    startY = clientY;
    clearTimeout(pressTimer);
    pressTimer = setTimeout(() => {
      if (!hasMoved) {
        if (navigator.vibrate) navigator.vibrate(40);
        enterSelectionMode(note.id);
      }
    }, 450);
  };

  const movePress = (clientX, clientY) => {
    if (!pressTimer) return;
    if (Math.hypot(clientX - startX, clientY - startY) > 10) {
      hasMoved = true;
      clearTimeout(pressTimer);
      pressTimer = null;
    }
  };

  const cancelPress = () => {
    clearTimeout(pressTimer);
    pressTimer = null;
  };

  div.addEventListener('pointerdown', (e) => {
    if (e.target.closest('.note-actions') || e.target.closest('.note-items input') || e.target.closest('button')) return;
    startPress(e.clientX, e.clientY);
  });
  div.addEventListener('pointermove', (e) => {
    movePress(e.clientX, e.clientY);
  });
  div.addEventListener('pointerup', cancelPress);
  div.addEventListener('pointercancel', cancelPress);

  // Entire card opens editor, but when in selection mode it toggles selection
  div.addEventListener('click', (e) => {
    if (e.target.closest('.note-actions') || e.target.closest('.note-items input')) return;

    if (state.selectionMode) {
      e.stopPropagation();
      e.preventDefault();
      if (justEnteredSelectionMode) return;
      toggleNoteSelection(note.id);
      return;
    }

    if (isTrash) return;
    window.openEditModal(note.id);
  });

  // Apply note color
  if (note.color && note.color !== '#1e293b') {
    div.style.backgroundColor = `${note.color}15`; // 15 = tiny bit of opacity
    div.style.borderColor = `${note.color}40`;
  }

  // Attach mobile swipe gestures
  attachCardGestures(div, note);

  return div;
}

// ── Color Picker ──────────────────────────────────────────────
window.showColorPicker = (e, id) => {
  if (e && e.stopPropagation) e.stopPropagation();
  const existing = qs('.color-palette');
  if (existing) existing.remove();

  const palette = document.createElement('div');
  palette.className = 'color-palette';
  
  COLORS.forEach(color => {
    const swatch = document.createElement('div');
    swatch.className = 'color-swatch';
    swatch.style.backgroundColor = color;
    swatch.onclick = async (ev) => {
      ev.stopPropagation();
      try {
        if (id) {
          const note = state.notes.find(n => n.id == id);
          if (note) {
            note.color = color;
            note.updated_at = new Date().toISOString();
            renderNotes();
            await persistNotesLocal();
          }
        }
        if (state.editingNote) {
          state.editingNote.color = color;
          const modalContent = qs('#edit-modal-content');
          if (modalContent) modalContent.style.backgroundColor = `${color}25`;
        }
        palette.remove();
      } catch (err) { toast(err.message, 'error'); }
    };
    palette.appendChild(swatch);
  });

  const close = () => { palette.remove(); document.removeEventListener('click', close); };
  setTimeout(() => document.addEventListener('click', close), 10);

  let trigger = null;
  if (e && e.target) {
    trigger = e.target.closest('#btn-edit-palette, .note-action-btn') || e.target;
  }
  if (trigger) {
    const rect = trigger.getBoundingClientRect();
    palette.style.position = 'fixed';
    palette.style.left = `${Math.max(10, Math.min(rect.left, window.innerWidth - 170))}px`;
    palette.style.bottom = `${window.innerHeight - rect.top + 8}px`;
    palette.style.zIndex = '1150';
    document.body.appendChild(palette);
  } else {
    document.body.appendChild(palette);
  }
};

function esc(str) {
  return String(str ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ── Note Actions ──────────────────────────────────────────────
window.togglePin = async (id, pinned) => {
  const note = state.notes.find(n => n.id == id);
  if (!note) return;
  note.pinned = !pinned;
  note.updated_at = new Date().toISOString();
  renderNotes();
  await persistNotesLocal();
};

window.archiveNote = async (id, archived) => {
  const note = state.notes.find(n => n.id == id);
  if (!note) return;
  note.archived = !archived;
  note.updated_at = new Date().toISOString();
  renderNotes();
  toast(note.archived ? 'Nota arquivada.' : 'Nota restaurada.', 'success');
  await persistNotesLocal();
};

window.restoreNote = async (id) => {
  const note = state.notes.find(n => n.id == id);
  if (!note) return;
  note.in_trash = 0;
  note.deleted_at = null;
  note.updated_at = new Date().toISOString();
  renderNotes();
  toast('Nota restaurada!', 'success');
  await persistNotesLocal();
};

window.deleteNotePermanent = async (id) => {
  if (!confirm('Deseja excluir esta nota permanentemente? Esta ação não pode ser desfeita.')) return;
  const idx = state.notes.findIndex(n => n.id == id);
  if (idx !== -1) {
    state.notes.splice(idx, 1);
    renderNotes();
    toast('Nota excluída permanentemente.', 'success');
    await persistNotesLocal();
  }
};

window.emptyTrash = async () => {
  if (!confirm('Esvaziar a lixeira? Todas as notas excluídas serão apagadas definitivamente.')) return;
  state.notes = state.notes.filter(n => !n.in_trash && !n.deleted_at);
  renderNotes();
  toast('Lixeira esvaziada com sucesso.', 'success');
  await persistNotesLocal();
};

window.deleteNote = async (id) => {
  if (state.filter === 'trash') {
    return window.deleteNotePermanent(id);
  }
  const note = state.notes.find(n => n.id == id);
  if (!note) return;
  note.in_trash = 1;
  note.deleted_at = new Date().toISOString();
  renderNotes();
  await persistNotesLocal();

  showUndoToast('Nota movida para a lixeira.', async () => {
    note.in_trash = 0;
    note.deleted_at = null;
    note.updated_at = new Date().toISOString();
    renderNotes();
    toast('Nota restaurada!', 'success');
    await persistNotesLocal();
  });
};

window.toggleItem = async (checkbox, noteId, index) => {
  const li = checkbox.closest('.note-item');
  const isChecked = checkbox.checked;
  li.classList.toggle('done', isChecked);

  const note = state.notes.find(n => n.id == noteId);
  if (note && note.extra?.items && note.extra.items[index] !== undefined) {
    if (typeof note.extra.items[index] === 'object') {
      note.extra.items[index].done = isChecked;
    } else {
      note.extra.items[index] = { text: note.extra.items[index], done: isChecked };
    }
    note.updated_at = new Date().toISOString();
    await persistNotesLocal();
  }
};
function getGoogleCalendarUrl(note) {
  const title = encodeURIComponent(note.title || 'Compromisso');
  let desc = note.content || '';
  if (note.extra?.person) desc += `\nCom: ${note.extra.person}`;
  desc = encodeURIComponent(desc);
  
  const loc = encodeURIComponent(note.extra?.location || '');
  const dateStr = note.extra?.date || new Date().toISOString().split('T')[0];
  const timeStr = note.extra?.time || '09:00';
  
  const parts = dateStr.split('-');
  const year = parts[0] || '2026';
  const month = parts[1] || '01';
  const day = parts[2] || '01';

  const timeParts = timeStr.split(':');
  const hour = (timeParts[0] || '09').padStart(2, '0');
  const min = (timeParts[1] || '00').padStart(2, '0');
  const startStr = `${year}${month}${day}T${hour}${min}00`;
  
  const startObj = new Date(parseInt(year, 10), parseInt(month, 10) - 1, parseInt(day, 10), parseInt(hour, 10), parseInt(min, 10));
  const endObj = new Date(startObj.getTime() + 60 * 60 * 1000);
  const endYear = endObj.getFullYear();
  const endMonth = String(endObj.getMonth() + 1).padStart(2, '0');
  const endDay = String(endObj.getDate()).padStart(2, '0');
  const endHour = String(endObj.getHours()).padStart(2, '0');
  const endMin = String(endObj.getMinutes()).padStart(2, '0');
  const endStr = `${endYear}${endMonth}${endDay}T${endHour}${endMin}00`;

  return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${title}&details=${desc}&location=${loc}&dates=${startStr}/${endStr}`;
}
window.getGoogleCalendarUrl = getGoogleCalendarUrl;

window.addToCalendar = async (id) => {
  let note = state.notes.find(n => n.id === id);
  if (!note && state.editingNote?.id === id) note = state.editingNote;
  if (!note) return;
  const url = getGoogleCalendarUrl(note);
  window.open(url, '_blank');
  toast('📅 Abrindo Google Agenda para salvar compromisso...', 'info');
};

// ── AI Processing ─────────────────────────────────────────────
async function submitAI(text) {
  if (!text) { toast('Digite ou fale algo primeiro.', 'info'); return; }
  if (state.credits < 1) {
    toast('Sem créditos! Recarregue via PIX.', 'error');
    setTimeout(() => openModal('pix-modal'), 800);
    return;
  }

  const btn = qs('#btn-submit-ai');
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span> Processando...';

  try {
    const data      = await api('POST', '/ai.php', { text });
    state.credits   = data.credits_remaining;
    updateCreditsUI();
    state.notes     = [...data.notes, ...state.notes];
    renderNotes();
    await persistNotesLocal();
    closeModal('ai-modal');
    qs('#ai-input').value = '';
    toast(`✨ ${data.notes.length} nota(s) criada(s)! Restam ${state.credits} créditos.`, 'success');
  } catch (e) {
    toast(e.message, 'error');
  } finally {
    btn.disabled = false;
    btn.innerHTML = '✨ Criar Notas';
  }
}

qs('#btn-open-ai').addEventListener('click', () => openModal('ai-modal'));
qs('#btn-close-ai').addEventListener('click', () => closeModal('ai-modal'));

let lastAiRequest = 0;
qs('#btn-submit-ai').addEventListener('click', async () => {
  const now = Date.now();
  if (now - lastAiRequest < 2000) {
    toast('Aguarde 2 segundos entre envios.', 'info');
    return;
  }
  lastAiRequest = now;
  submitAI(qs('#ai-input').value.trim());
});

// ── Voice Input ───────────────────────────────────────────────
let recognition = null;

const startVoice = () => {
  if (state.voiceActive) { stopVoice(); return; }

  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SR) { toast('Seu navegador não suporta reconhecimento de voz.', 'error'); return; }

  recognition = new SR();
  recognition.lang           = 'pt-BR';
  recognition.interimResults = false;
  recognition.maxAlternatives = 1;

  recognition.onstart = () => {
    state.voiceActive = true;
    qsa('#btn-voice, #btn-voice-modal').forEach(b => b.classList.add('active-voice'));
    qs('#voice-indicator').classList.add('active');
    openModal('ai-modal');
  };
  recognition.onresult = (e) => {
    const transcript = e.results[0][0].transcript;
    const input = qs('#ai-input');
    input.value = (input.value ? input.value + ' ' : '') + transcript;
    qs('#voice-indicator').classList.remove('active');
    
    // Auto-submit after a tiny bit of feedback
    toast('🎙️ Voz captada! Processando agora...', 'info');
    setTimeout(() => submitAI(qs('#ai-input').value.trim()), 1000);
  };
  recognition.onend   = stopVoice;
  recognition.onerror = () => { toast('Erro no reconhecimento de voz.', 'error'); stopVoice(); };
  recognition.start();
};

qs('#btn-voice')?.addEventListener('click', startVoice);
qs('#btn-voice-modal')?.addEventListener('click', startVoice);

function stopVoice() {
  state.voiceActive = false;
  qsa('#btn-voice, #btn-voice-modal').forEach(b => b.classList.remove('active-voice'));
  qs('#voice-indicator').classList.remove('active');
  recognition?.stop();
}

// ── Manual Note Creation ──────────────────────────────────────
