// ── Theme Manager ─────────────────────────────────────────────
const ThemeManager = {
  themes: ['keep', 'dark', 'oled', 'paper'],
  init() {
    const theme = localStorage.getItem('keepai-theme') || 'keep';
    this.apply(theme);
  },
  apply(theme) {
    document.body.classList.remove('theme-keep', 'theme-oled', 'theme-paper');
    if (theme === 'keep') document.body.classList.add('theme-keep');
    else if (theme === 'oled') document.body.classList.add('theme-oled');
    else if (theme === 'paper') document.body.classList.add('theme-paper');
    localStorage.setItem('keepai-theme', theme);
  },
  toggle() {
    const current = localStorage.getItem('keepai-theme') || 'keep';
    const idx = this.themes.indexOf(current);
    const next = this.themes[(idx + 1) % this.themes.length];
    this.apply(next);
    const names = { keep: 'Google Keep (Claro)', dark: 'Dark Slate (Futurista)', oled: 'OLED Black (Econômico)', paper: 'Warm Paper (Notion)' };
    toast(`Tema: ${names[next] || next}`, 'info');
  }
};

qs('#btn-theme')?.addEventListener('click', () => ThemeManager.toggle());

// ── Layout Manager (Grade vs Lista - Estilo Google Keep) ──────
const LayoutManager = {
  current: 'grid',
  lastToggle: 0,
  init() {
    this.current = localStorage.getItem('keepai-layout') || 'grid';
    this.apply(this.current, false);
  },
  apply(layout, notify = true) {
    this.current = layout;
    localStorage.setItem('keepai-layout', layout);
    const grid = qs('#notes-grid');
    const btn = qs('#btn-toggle-layout');

    if (grid) {
      grid.classList.toggle('layout-grid', layout === 'grid');
      grid.classList.toggle('layout-list', layout === 'list');
    }

    if (btn) {
      if (layout === 'list') {
        btn.innerHTML = '<i data-lucide="layout-grid"></i>';
        btn.title = typeof t === 'function' ? t('header.toggle_to_grid') : 'Mudar para visualização em grade (2 colunas)';
      } else {
        btn.innerHTML = '<i data-lucide="rows-3"></i>';
        btn.title = typeof t === 'function' ? t('header.toggle_to_list') : 'Mudar para visualização em lista (1 coluna)';
      }
      if (window.lucide) lucide.createIcons();
    }

    if (notify) {
      const msg = layout === 'list'
        ? (typeof t === 'function' ? t('toasts.layout_list') : 'Visualização em lista (1 coluna)')
        : (typeof t === 'function' ? t('toasts.layout_grid') : 'Visualização em grade (2 colunas)');
      toast(msg, 'info');
    }
  },
  toggle(e) {
    if (e && e.stopPropagation) e.stopPropagation();
    if (e && e.preventDefault) e.preventDefault();
    const now = Date.now();
    if (now - this.lastToggle < 300) return; // Prevent double triggers
    this.lastToggle = now;
    const next = this.current === 'grid' ? 'list' : 'grid';
    this.apply(next, true);
  }
};
window.LayoutManager = LayoutManager;

qs('#btn-toggle-layout')?.addEventListener('click', (e) => LayoutManager.toggle(e));

