// ── PWA Install Logic ─────────────────────────────────────────
window.deferredPrompt = window.deferredPrompt || null;
const BANNER_COOLDOWN = 1000 * 60 * 60 * 24; // 24 hours

function showInstallBanner() {
  const isStandalone = window.matchMedia('(display-mode: standalone)').matches || 
                       window.navigator.standalone === true;
  if (isStandalone) return;
  const lastDismissed = localStorage.getItem('pwa-dismissed');
  const now = Date.now();
  if (lastDismissed && (now - lastDismissed < BANNER_COOLDOWN)) return;
  const banner = qs('#install-banner');
  if (banner) banner.classList.add('visible');
}
window.showInstallBanner = showInstallBanner;

window.addEventListener('beforeinstallprompt', (e) => {
  e.preventDefault();
  window.deferredPrompt = e;
  showInstallBanner();
  updatePwaInstallUI();
});

async function handleInstallPwa() {
  const isStandalone = window.matchMedia('(display-mode: standalone)').matches || 
                       window.navigator.standalone === true || 
                       document.referrer.includes('android-app://');
  if (isStandalone) {
    toast('O Keep AI já está instalado e rodando como aplicativo!', 'success');
    return;
  }

  if (window.deferredPrompt) {
    try {
      window.deferredPrompt.prompt();
      const { outcome } = await window.deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        toast('🚀 Keep AI instalado com sucesso!', 'success');
        window.deferredPrompt = null;
        qs('#install-banner')?.classList.remove('visible');
        updatePwaInstallUI();
      }
      return;
    } catch (err) {
      console.error('Erro no prompt de instalação:', err);
    }
  }

  // Fallback para iOS / Desktop / navegadores sem prompt automático
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
  const isAndroid = /Android/.test(navigator.userAgent);

  const boxIOS = qs('#install-guide-ios');
  const boxAndroid = qs('#install-guide-android');
  const boxDesktop = qs('#install-guide-desktop');

  if (boxIOS) boxIOS.style.display = isIOS ? 'block' : 'none';
  if (boxAndroid) boxAndroid.style.display = (isAndroid && !isIOS) ? 'block' : 'none';
  if (boxDesktop) boxDesktop.style.display = (!isIOS && !isAndroid) ? 'block' : 'none';
  if (!isIOS && !isAndroid && boxDesktop) boxDesktop.style.display = 'block';

  openModal('modal-install-guide');
}
window.handleInstallPwa = handleInstallPwa;

function updatePwaInstallUI() {
  const isStandalone = window.matchMedia('(display-mode: standalone)').matches || 
                       window.navigator.standalone === true;
  const headerBtn = qs('#btn-header-install');
  const sidebarBtnText = qs('#sidebar-install-text');
  
  if (isStandalone) {
    if (headerBtn) headerBtn.style.display = 'none';
    if (sidebarBtnText) sidebarBtnText.textContent = 'App Instalado ✓';
  } else {
    if (headerBtn) headerBtn.style.display = 'inline-flex';
  }
}
window.updatePwaInstallUI = updatePwaInstallUI;

qs('#btn-install-now')?.addEventListener('click', handleInstallPwa);

