qs('#input-restore-backup')?.addEventListener('change', async (e) => {
  const file = e.target.files[0];
  if (!file) return;
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    const notesToRestore = Array.isArray(data.notes) ? data.notes : (Array.isArray(data) ? data : null);
    if (!notesToRestore || !notesToRestore.length) {
      toast('Nenhuma nota encontrada no arquivo de backup.', 'error');
      return;
    }
    if (!confirm(`Deseja importar ${notesToRestore.length} notas deste backup?`)) return;

    showLoading('Restaurando notas...');
    notesToRestore.forEach(n => {
      const existingIdx = state.notes.findIndex(ex => ex.id == n.id);
      if (existingIdx !== -1) {
        state.notes[existingIdx] = n;
      } else {
        state.notes.push(n);
      }
    });
    await persistNotesLocal();
    renderNotes();
    hideLoading();
    closeModal('modal-drive-backup');
    toast(`✅ ${notesToRestore.length} notas importadas com sucesso!`, 'success');
  } catch (err) {
    hideLoading();
    toast('Falha ao ler arquivo: ' + err.message, 'error');
  } finally {
    e.target.value = '';
  }
});

// ── Viral Sharing ──────────────────────────────────────────────
let isSharing = false;
const isMobile = () => {
  const ua = navigator.userAgent;
  // Explicitly exclude Windows Desktop to avoid native share fallback "Try again" error
  if (/Windows NT/i.test(ua)) return false; 
  return /Android|iPhone|iPad|iPod|Opera Mini|IEMobile|Mobile/i.test(ua);
};

window.shareApp = async () => {
  if (isSharing) return;
  const appUrl = window.location.href.split('index.html')[0].split('?')[0].split('#')[0] + '?v=46';
  const e = (cp) => String.fromCodePoint(cp);
  
  if (isMobile() && navigator.share) {
    const richText = `Confira este App de notas com IA!\n-------------------\n${e(0x1F680)} Keep AI`;
    try { isSharing = true; await navigator.share({ title: 'Keep AI', text: richText, url: appUrl }); return; } catch (e) {} finally { isSharing = false; }
  }
  
  const cleanText = `Confira este App de notas com IA!\n-------------------\n[Keep AI] ${appUrl}`;
  openShareModal({ title: 'Keep AI', text: cleanText, url: appUrl });
};

window.shareNote = async (id) => {
  if (isSharing) return;
  const note = state.notes.find(n => n.id === id);
  if (!note) return;
  const appUrl = window.location.href.split('index.html')[0].split('?')[0].split('#')[0] + '?v=46';
  
  const typeIconsASCII = { 'generic': '[NOTA]', 'shopping-list': '[CHECKLIST]', 'checklist': '[CHECKLIST]', 'event': '[AGENDA]', 'appointment': '[AGENDA]', 'agenda': '[AGENDA]' };
  const getShareText = (useEmoji) => {
    // 📝, ☑️, 📅, 🚀, 👉
    const e = (cp) => String.fromCodePoint(cp);
    const icon = useEmoji ? (typeIconsEmoji[note.type] || e(0x1F4DD)) : (typeIconsASCII[note.type] || '[Nota]');
    const sep = '-------------------';
    const rocket = useEmoji ? e(0x1F680) : '';
    const hand = useEmoji ? e(0x1F449) : '=>';
    
    // Crawler-First: Link at the top guarantees og:image preview for long content
    let t = `${icon} *${(note.title || 'Nota').toUpperCase()}*\n${hand} ${appUrl}\n${sep}\n\n`;
    if ((note.type === 'shopping-list' || note.type === 'checklist') && note.extra?.items) t += note.extra.items.map(it => `· ${it}`).join('\n') + '\n';
    else if (note.content) t += `${note.content}\n`;
    t += `\n${sep}\n${rocket} _Keep AI_`;
    return t;
  };
  
  const typeIconsEmoji = { 'generic': '\uD83D\uDCDD', 'shopping-list': '\u2611\uFE0F', 'checklist': '\u2611\uFE0F', 'event': '\uD83D\uDCC5', 'appointment': '\uD83D\uDCC5', 'agenda': '\uD83D\uDCC5' };

  if (isMobile() && navigator.share) {
    const richText = getShareText(true);
    try { isSharing = true; await navigator.share({ title: note.title, text: richText, url: appUrl }); return; } catch (e) {} finally { isSharing = false; }
  }
  
  // Desktop/Windows: Use Clean ASCII to avoid mangled ??
  const cleanText = getShareText(false);
  openShareModal({ title: note.title || 'Nota', text: cleanText, url: appUrl });
};

function openShareModal(data) {
  const modal = qs('#share-modal');
  if (!modal) return;
  modal.classList.add('open');
  qs('#share-url-input').value = data.url;
  const encodedText = encodeURIComponent(data.text);
  qs('#share-whatsapp').href = `https://wa.me/?text=${encodedText}`;
  qs('#share-telegram').href = `https://t.me/share/url?url=${encodeURIComponent(data.url)}&text=${encodedText}`;
  qs('#share-email').href = `mailto:?subject=${encodeURIComponent(data.title)}&body=${encodedText}`;
  const copyBtn = qs('#share-copy');
  const newCopyBtn = copyBtn.cloneNode(true);
  copyBtn.parentNode.replaceChild(newCopyBtn, copyBtn);
  newCopyBtn.addEventListener('click', async () => {
    await navigator.clipboard.writeText(data.text);
    const msg = typeof t === 'function' ? t('modals.share.copied') : 'Copiado!';
    toast(msg, 'success');
  });
}
