qs('#image-upload-input')?.addEventListener('change', async (e) => {
  const file = e.target.files[0];
  if (!file || !file.type.startsWith('image/')) {
    toast('Selecione um arquivo de imagem válido.', 'error');
    return;
  }
  const reader = new FileReader();
  reader.onload = (ev) => {
    const img = new Image();
    img.onload = () => {
      const maxDim = 1400;
      let w = img.width, h = img.height;
      if (w > maxDim || h > maxDim) {
        if (w > h) { h = Math.round((h * maxDim) / w); w = maxDim; }
        else { w = Math.round((w * maxDim) / h); h = maxDim; }
      }
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);
      const compressedDataUrl = canvas.toDataURL('image/jpeg', 0.82);

      if (state.editingNote) {
        state.editingNote.image = compressedDataUrl;
        updateEditModalImagePreview(compressedDataUrl);
        toast('Imagem carregada e otimizada!', 'info');
      }
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
});

function updateEditModalImagePreview(base64) {
  const preview = qs('#edit-image-preview');
  if (!preview) return;
  if (base64) {
    preview.innerHTML = `<img src="${base64}" alt="Preview"><button class="btn-remove-image" id="btn-modal-remove-image"><i data-lucide="x"></i></button>`;
    preview.classList.remove('hidden');
    if (window.lucide) lucide.createIcons();
  } else { preview.innerHTML = ''; preview.classList.add('hidden'); }
}

document.addEventListener('click', (e) => {
  if (e.target.closest('#btn-modal-remove-image')) { if (state.editingNote) state.editingNote.image = null; updateEditModalImagePreview(null); toast('Imagem removida.', 'info'); }
});

// Global Helpers
window.openModal = openModal;
window.closeModal = closeModal;

function initAskAI() {
  const input = qs('#ask-ai-input');
  const sendBtn = qs('#btn-send-ask-ai');
  const messages = qs('#ask-ai-messages');
  const openBtn = qs('#btn-open-ask-ai');
  const closeBtn = qs('#btn-close-ask-ai');

  if (openBtn) openBtn.onclick = () => openModal('ask-ai-modal');
  if (closeBtn) closeBtn.onclick = () => closeModal('ask-ai-modal');

  const send = async () => {
    const q = input.value.trim();
    if (!q) return;

    // Mensagem do usuário
    const userMsg = document.createElement('div');
    userMsg.className = 'chat-msg user';
    userMsg.innerHTML = `<div class="msg-bubble">${esc(q)}</div>`;
    messages.appendChild(userMsg);
    input.value = '';
    messages.scrollTop = messages.scrollHeight;

    // Mensagem de loading do assistente
    const loadingMsg = document.createElement('div');
    loadingMsg.className = 'chat-msg assistant';
    loadingMsg.innerHTML = `<div class="msg-bubble"><em>Consultando suas notas...</em></div>`;
    messages.appendChild(loadingMsg);
    messages.scrollTop = messages.scrollHeight;

    try {
      const activeNotes = (state.notes || []).filter(n => !n.archived && !n.in_trash && !n.deleted_at);
      const res = await api('POST', '/ai_chat.php', { query: q, history: chatHistory, notes: activeNotes });
      chatHistory.push({ role: 'user', content: q });
      chatHistory.push({ role: 'assistant', content: res.answer });
      
      // Formatar citações de notas [nota:ID:Título] em chips clicáveis
      let formatted = esc(res.answer).replace(/\[nota:(\d+):([^\]]+)\]/g, (match, id, title) => {
        return `<span class="note-citation-chip" onclick="openEditModal(${id})">📄 ${title}</span>`;
      });

      loadingMsg.querySelector('.msg-bubble').innerHTML = formatted;
      if (window.lucide) lucide.createIcons();
      messages.scrollTop = messages.scrollHeight;

      if (res.credits_remaining !== undefined) {
        state.credits = res.credits_remaining;
        updateCreditsUI();
      }
    } catch (err) {
      loadingMsg.querySelector('.msg-bubble').innerHTML = `<span style="color:var(--red)">${esc(err.message || 'Erro ao consultar Memória Digital.')}</span>`;
    }
  };

  if (sendBtn) sendBtn.onclick = send;
  if (input) input.addEventListener('keydown', (e) => { if (e.key === 'Enter') send(); });

  qsa('.chat-sugg-btn').forEach(btn => {
    btn.onclick = () => {
      input.value = btn.dataset.query;
      send();
    };
  });
}

// ── Visão Computacional (Foto OCR) ────────────────────────────
function initVisionOCR() {
  const openBtn = qs('#btn-open-vision');
  const fileInp = qs('#vision-file-input');
  const cameraInp = qs('#vision-camera-input');
  const placeholder = qs('#vision-placeholder');
  const preview = qs('#vision-img-preview');
  const processBtn = qs('#btn-process-vision');
  const modeSelect = qs('#vision-mode-select');
  const closeBtn = qs('#btn-close-vision');
  const closeBtnAlt = qs('#btn-close-vision-alt');
  const triggerCameraBtn = qs('#btn-trigger-camera');
  const triggerGalleryBtn = qs('#btn-trigger-gallery');
  const dropArea = qs('#vision-drop-area');

  let currentBase64 = null;

  const openVision = () => {
    currentBase64 = null;
    preview.classList.add('hidden');
    placeholder.classList.remove('hidden');
    processBtn.disabled = true;
    openModal('vision-modal');
  };

  if (openBtn) openBtn.onclick = openVision;
  if (qs('#btn-mode-vision')) qs('#btn-mode-vision').onclick = () => { closeModal('ai-modal'); openVision(); };
  if (closeBtn) closeBtn.onclick = () => closeModal('vision-modal');
  if (closeBtnAlt) closeBtnAlt.onclick = () => closeModal('vision-modal');

  // Trigger camera or gallery buttons
  if (triggerCameraBtn) {
    triggerCameraBtn.onclick = (e) => {
      e.stopPropagation();
      cameraInp?.click();
    };
  }
  if (triggerGalleryBtn) {
    triggerGalleryBtn.onclick = (e) => {
      e.stopPropagation();
      fileInp?.click();
    };
  }
  if (placeholder) {
    placeholder.onclick = (e) => {
      if (e.target.closest('#btn-trigger-camera') || e.target.closest('#btn-trigger-gallery')) return;
      fileInp?.click();
    };
  }

  const handleImage = (file) => {
    if (!file || !file.type.startsWith('image/')) return toast('Selecione uma imagem válida.', 'error');
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const maxDim = 1600;
        let w = img.width, h = img.height;
        if (w > maxDim || h > maxDim) {
          if (w > h) { h = Math.round((h * maxDim) / w); w = maxDim; }
          else { w = Math.round((w * maxDim) / h); h = maxDim; }
        }
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
        currentBase64 = dataUrl.split(',')[1];
        preview.src = dataUrl;
        preview.classList.remove('hidden');
        placeholder.classList.add('hidden');
        processBtn.disabled = false;
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  };

  if (fileInp) fileInp.onchange = (e) => { if (e.target.files?.[0]) handleImage(e.target.files[0]); };
  if (cameraInp) cameraInp.onchange = (e) => { if (e.target.files?.[0]) handleImage(e.target.files[0]); };

  // Drag & drop
  if (dropArea) {
    dropArea.ondragover = (e) => { e.preventDefault(); dropArea.classList.add('drag-over'); };
    dropArea.ondragleave = () => dropArea.classList.remove('drag-over');
    dropArea.ondrop = (e) => {
      e.preventDefault();
      dropArea.classList.remove('drag-over');
      if (e.dataTransfer?.files?.[0]) handleImage(e.dataTransfer.files[0]);
    };
  }

  if (processBtn) {
    processBtn.onclick = async () => {
      if (!currentBase64) return;
      processBtn.disabled = true;
      processBtn.textContent = 'Processando com IA...';
      try {
        const mode = modeSelect?.value || 'auto';
        let prompt = "Analise esta imagem e extraia todas as informações úteis em português. Se for uma lista ou compras, liste os itens claramente. Se tiver data ou compromissos, indique a data e horário.";
        if (mode === 'shopping') prompt = "Identifique todos os itens ou produtos nesta imagem e liste-os em tópicos como uma lista de compras/tarefas.";
        else if (mode === 'event') prompt = "Identifique datas, horários, nomes de pessoas e locais para agendamento de eventos a partir desta imagem.";
        else if (mode === 'text') prompt = "Transcreva fielmente todo o texto visível nesta imagem.";

        const res = await api('POST', '/ai_vision.php', { prompt, image: currentBase64 });
        closeModal('vision-modal');
        
        qs('#ai-input').value = res.text;
        openModal('ai-modal');
        toast('Texto extraído com sucesso! Revise e clique em Criar Notas.', 'success');
        if (res.credits_remaining !== undefined) {
          state.credits = res.credits_remaining;
          updateCreditsUI();
        }
      } catch (err) {
        toast(err.message || 'Erro ao processar imagem.', 'error');
      } finally {
        processBtn.disabled = false;
        processBtn.textContent = '✨ Processar Imagem (1 crédito)';
      }
    };
  }
}

// ── Gravador de Áudio Whisper ──────────────────────────────────
function initWhisperAudio() {
  const toggleBtn = qs('#btn-toggle-record');
  const label = qs('#btn-record-label');
  const status = qs('#audio-status-text');
  const timerEl = qs('#audio-timer');
  const wave = qs('#audio-wave');
  const cancelBtn = qs('#btn-cancel-audio');
  const closeBtn = qs('#btn-close-audio');

  let mediaRecorder = null;
  let audioChunks = [];
  let recordInterval = null;
  let recordSeconds = 0;
  let isRecording = false;

  const openAudio = () => {
    isRecording = false;
    recordSeconds = 0;
    timerEl.textContent = '00:00';
    label.textContent = 'Iniciar Gravação';
    status.textContent = 'Clique para iniciar a gravação. A IA transcreverá suas ideias e organizará suas notas.';
    wave.classList.remove('recording');
    openModal('audio-modal');
  };

  if (qs('#btn-mode-audio')) qs('#btn-mode-audio').onclick = () => { closeModal('ai-modal'); openAudio(); };
  if (closeBtn) closeBtn.onclick = () => { stopRecording(false); closeModal('audio-modal'); };
  if (cancelBtn) cancelBtn.onclick = () => { stopRecording(false); closeModal('audio-modal'); };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorder = new MediaRecorder(stream);
      audioChunks = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunks.push(e.data);
      };

      mediaRecorder.onstop = async () => {
        stream.getTracks().forEach(t => t.stop());
        if (!isRecording) return;
        const audioBlob = new Blob(audioChunks, { type: 'audio/webm' });
        await uploadAndTranscribe(audioBlob);
      };

      mediaRecorder.start();
      isRecording = true;
      wave.classList.add('recording');
      label.textContent = 'Parar e Processar';
      status.textContent = 'Gravando... Fale suas notas, compras ou compromissos.';

      recordSeconds = 0;
      recordInterval = setInterval(() => {
        recordSeconds++;
        const mins = String(Math.floor(recordSeconds / 60)).padStart(2, '0');
        const secs = String(recordSeconds % 60).padStart(2, '0');
        timerEl.textContent = `${mins}:${secs}`;
        if (recordSeconds >= 120) stopRecording(true);
      }, 1000);

    } catch (err) {
      toast('Acesso ao microfone negado ou indisponível.', 'error');
    }
  };

  const stopRecording = (shouldProcess = true) => {
    if (recordInterval) clearInterval(recordInterval);
    if (!isRecording) return;
    isRecording = shouldProcess;
    if (mediaRecorder && mediaRecorder.state !== 'inactive') {
      mediaRecorder.stop();
    }
    wave.classList.remove('recording');
  };

  const uploadAndTranscribe = async (blob) => {
    status.textContent = 'Transcrevendo áudio com Whisper e gerando notas...';
    label.textContent = 'Processando...';
    toggleBtn.disabled = true;

    const formData = new FormData();
    formData.append('audio', blob, 'gravacao.webm');

    try {
      const res = await fetch(`${API}/ai_audio.php`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${state.token}` },
        body: formData
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Erro na transcrição.');

      closeModal('audio-modal');
      if (data.notes && Array.isArray(data.notes)) {
        state.notes = [...data.notes, ...state.notes];
        renderNotes();
        await persistNotesLocal();
      }
      toast(`Áudio processado! ${data.notes?.length || 1} nota(s) criada(s).`, 'success');
      if (data.credits_remaining !== undefined) {
        state.credits = data.credits_remaining;
        updateCreditsUI();
      }
    } catch (err) {
      toast(err.message || 'Erro ao processar áudio.', 'error');
      status.textContent = 'Erro ao processar áudio.';
    } finally {
      toggleBtn.disabled = false;
      label.textContent = 'Iniciar Gravação';
    }
  };

  if (toggleBtn) {
    toggleBtn.onclick = () => {
      if (!isRecording) startRecording();
      else stopRecording(true);
    };
  }
}

// ── Ações de IA dentro da Nota ────────────────────────────────
function initAITransform() {
  const triggerBtn = qs('#btn-edit-ai-transform');
  const menu = qs('#ai-transform-menu');
  if (!triggerBtn || !menu) return;

  triggerBtn.onclick = (e) => {
    e.stopPropagation();
    const isHidden = menu.classList.contains('hidden');
    if (isHidden) {
      const rect = triggerBtn.getBoundingClientRect();
      menu.style.position = 'fixed';
      menu.style.left = `${Math.max(10, Math.min(rect.left, window.innerWidth - 240))}px`;
      menu.style.bottom = `${window.innerHeight - rect.top + 8}px`;
      menu.style.zIndex = '1150';
      menu.classList.remove('hidden');
    } else {
      menu.classList.add('hidden');
    }
  };

  document.addEventListener('click', () => menu.classList.add('hidden'));

  qsa('.ai-menu-item').forEach(item => {
    item.onclick = async (e) => {
      e.stopPropagation();
      menu.classList.add('hidden');
      const action = item.dataset.action;
      const lang = item.dataset.lang || 'en';

      const contentInp = qs('#edit-content');
      const text = contentInp.value.trim();
      if (!text) return toast('Escreva algum texto na nota antes de usar a IA.', 'info');

      toast('Processando transformação com IA...', 'info');
      try {
        const res = await api('POST', '/ai_transform.php', { action, text, target_lang: lang });
        if (action === 'to_checklist') {
          qs('#edit-content').classList.add('hidden');
          qs('#list-editor-container').classList.remove('hidden');
          const grid = qs('#modal-list-items');
          grid.innerHTML = '';
          const items = Array.isArray(res.result) ? res.result : [res.result];
          items.forEach(it => addListItemToModal(it));
          toast('Convertido para checklist!', 'success');
        } else {
          contentInp.value = res.result;
          toast('Nota atualizada com IA!', 'success');
        }
        if (res.credits_remaining !== undefined) {
          state.credits = res.credits_remaining;
          updateCreditsUI();
        }
      } catch (err) {
        toast(err.message || 'Falha na transformação de IA.', 'error');
      }
    };
  });
}

